"""rag_tool.py  --  the search_kb tool (RAG: retrieval)   >>> YOU DO NOT EDIT THIS FILE <<<

RAG = Retrieval Augmented Generation. This file is the "R": given a question, find the best helpdesk articles.
The SAME code runs in two places:
  - here, for the Practice gateway: matches WORDS (no AWS, so the lab always runs)
  - inside the AWS Lambda behind your Gateway: matches MEANING with Amazon Titan Embeddings v2 (the Lambda passes in `embed`)
The result says which one was used ("mode"), so you can always see it.
"""
import math
import re

STOP = set("the a an and or of to in on for with is are was be it this that my me i you your can how do does what when where which not from at by as if".split())


def words(text):
    ws = {w for w in re.findall(r"[a-z0-9]+", str(text).lower()) if len(w) > 2 and w not in STOP}
    return {w[:-1] if len(w) > 3 and w.endswith("s") else w for w in ws}


def load_kb_dir(path):
    """Read the helpdesk articles (*.md) -> [{"id", "title", "text"}]"""
    docs = []
    for p in sorted(path.glob("KB-*.md")):
        text = p.read_text(encoding="utf-8")
        m = re.search(r"\*\*ID:\*\*\s*(KB-\d+)", text)
        title = next((ln.lstrip("# ").strip() for ln in text.splitlines() if ln.startswith("#")), p.stem)
        docs.append({"id": m.group(1) if m else p.stem.split("_")[0], "title": title, "text": text.strip()})
    return docs


def _keyword_scores(query, docs):
    qw = words(query)
    df = {}
    for d in docs:
        for w in words(d["text"]):
            df[w] = df.get(w, 0) + 1
    out = []
    for d in docs:
        dw = words(d["text"] + " " + d["title"])
        out.append(sum(math.log(1 + len(docs) / df.get(w, 1)) for w in qw & dw) / (len(qw) or 1) / 3.0)   # roughly 0..1
    return out


def _cosine(a, b):
    na, nb = math.sqrt(sum(x * x for x in a)), math.sqrt(sum(x * x for x in b))
    return sum(x * y for x, y in zip(a, b)) / (na * nb) if na and nb else 0.0


def make_search(docs, embed=None):
    """embed = None  -> word matching.   embed = f(list of text) -> list of vectors  -> meaning matching (falls back to words if it fails)."""
    cache = {}

    def search_kb(query="", top_k=3):
        if not isinstance(query, str) or not query.strip():
            return {"error": "query must be a non-empty text."}
        query = query.strip()[:300]
        try:
            top_k = max(1, min(5, int(top_k)))
        except (TypeError, ValueError):
            top_k = 3
        mode = "keyword"
        scores = None
        if embed is not None:
            try:
                if "vecs" not in cache:
                    cache["vecs"] = embed([d["title"] + "\n" + d["text"] for d in docs])      # once per warm Lambda
                qv = embed([query])[0]
                scores = [_cosine(qv, v) for v in cache["vecs"]]
                mode = "titan-embed-text-v2"
            except Exception as e:                                                    # noqa: BLE001
                mode = f"keyword (embedding failed: {type(e).__name__})"
        if scores is None:
            scores = _keyword_scores(query, docs)
        ranked = sorted(zip(scores, docs), key=lambda x: -x[0])[:top_k]
        return {"mode": mode, "query": query,
                "results": [{"id": d["id"], "title": d["title"], "score": round(s, 3), "text": d["text"][:700]} for s, d in ranked]}

    return search_kb
